// COR-07 — the permis source is quarantined. Since D-40 the quarantine and its reason are served
// by `GET /v1/datasets` (declared in the backend catalogue) and « Données & méthode » renders them
// in the detail of the permis source (DatasetDetail since 04.5-11): this test reads the served answer (fixture generated by the backend and
// pinned to the catalogue by test_datasets_reutilisation.py) and the refusal of the permis route
// itself (COR-07 fixture), never a copy written in the frontend.
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { render } from '@testing-library/svelte';
import { describe, expect, it } from 'vitest';
import DatasetDetail from '$lib/components/DatasetDetail.svelte';
import type { DatasetPublic } from '$lib/api/datasets';
import datasetsApi from './__fixtures__/datasets-api.json';

const PERMIS = (datasetsApi.donnees as DatasetPublic[]).find((jeu) => jeu.nom === 'permis')!;
const ROUTE = JSON.parse(
	readFileSync(
		resolve(process.cwd(), '../docs/audit-stabilisation-2026-09-08/lot-02/cor07-api-fixture.json'),
		'utf8'
	)
);

describe('COR-07 permis source quarantine', () => {
	it('is served quarantined by /v1/datasets, with the coverage and date explanation', () => {
		expect(PERMIS.statut).toBe('quarantined');
		const motif = PERMIS.quarantaine!;
		expect(motif).toContain('département 93');
		expect(motif).toContain('ne signifie pas absence de permis');
		expect(motif).toContain('date de commencement ne la remplace pas');
	});

	it('renders the « Non qualifié » card with the served reason and none of the forbidden claims', () => {
		const { container } = render(DatasetDetail, {
			props: { jeu: PERMIS, departementsInstance: ['44', '85'] }
		});
		const text = container.textContent ?? '';
		expect(text).toContain('Non qualifié');
		expect(text).toContain(PERMIS.quarantaine!);
		expect(text).not.toContain('PC 044 109 24 00001');
		expect(text).not.toContain('déposés et autorisés');
		expect(text).not.toContain('Essayer maintenant');
		expect(text).not.toContain('Vendée (85). Extension');
	});

	it('agrees with the refusal payload of the permis route (empty list, same attribution)', () => {
		expect(ROUTE.statut).toBe('indisponible');
		expect(ROUTE.donnees).toEqual([]);
		expect(ROUTE.raison).toContain('departement 93');
		expect(ROUTE.raison).toContain('ne signifie pas absence de permis');
		expect(ROUTE.meta.source.nom).toBe(PERMIS.provenance!.nom);
		expect(ROUTE.meta.source.producteur).toBe(PERMIS.provenance!.producteur);
		expect(ROUTE.meta.source.licence).toBe(PERMIS.reutilisation!.licence);
	});
});
